import{_ as r,o as a,c as d,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"⚙️ 设置","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/settings.md","filePath":"features/settings.md"}'),o={name:"features/settings.md"};function n(h,t,s,i,l,b){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="⚙️-设置" tabindex="-1">⚙️ 设置 <a class="header-anchor" href="#⚙️-设置" aria-label="Permalink to &quot;⚙️ 设置&quot;">​</a></h1><p>设置页面让您根据个人喜好定制 EmuTrain 的外观与行为。</p><hr><h2 id="主题设置" tabindex="-1">主题设置 <a class="header-anchor" href="#主题设置" aria-label="Permalink to &quot;主题设置&quot;">​</a></h2><h3 id="深浅色模式" tabindex="-1">深浅色模式 <a class="header-anchor" href="#深浅色模式" aria-label="Permalink to &quot;深浅色模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><strong>深色模式</strong></td><td>手动切换到深色 / 浅色主题</td></tr><tr><td><strong>子夜模式</strong></td><td>在深色基础上使用纯黑背景，更适合 OLED 屏幕省电</td></tr><tr><td><strong>跟随系统</strong></td><td>自动随系统深浅色设置切换，优先级最高</td></tr></tbody></table><h3 id="主题色" tabindex="-1">主题色 <a class="header-anchor" href="#主题色" aria-label="Permalink to &quot;主题色&quot;">​</a></h3><p>EmuTrain 支持 <strong>Material You</strong> 动态取色：</p><ul><li>默认使用设备壁纸的<strong>莫奈取色</strong>（仅支持 Android 12+）</li><li>也可手动从色轮中<strong>自定义种子颜色</strong></li><li>清除自定义颜色后自动恢复莫奈取色</li></ul><hr><h2 id="图标显示" tabindex="-1">图标显示 <a class="header-anchor" href="#图标显示" aria-label="Permalink to &quot;图标显示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><strong>显示列车图标</strong></td><td>在搜索结果中显示对应动车组车型的图标图片</td></tr><tr><td><strong>显示路局图标</strong></td><td>在搜索结果中显示所属路局的 logo 图标</td></tr><tr><td><strong>显示相似走向</strong></td><td>搜索线路时同时显示走向相近的其他线路</td></tr></tbody></table><hr><h2 id="数据源设置" tabindex="-1">数据源设置 <a class="header-anchor" href="#数据源设置" aria-label="Permalink to &quot;数据源设置&quot;">​</a></h2><p>可为三类查询分别指定数据源，按个人喜好灵活搭配：</p><h3 id="车次查询数据源" tabindex="-1">车次查询数据源 <a class="header-anchor" href="#车次查询数据源" aria-label="Permalink to &quot;车次查询数据源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据源</th><th>描述</th></tr></thead><tbody><tr><td><strong>Rail.re</strong>（默认）</td><td>第三方 API，提供更丰富的数据，但可能缺少部分数据</td></tr><tr><td><strong>RailGo</strong></td><td>第三方 API，提供更丰富的数据，但可能缺少部分数据</td></tr><tr><td><strong>12306 官方</strong></td><td>官方数据源，最准确可靠，但不显示重连、城际等</td></tr></tbody></table><h3 id="车号-交路查询数据源" tabindex="-1">车号 / 交路查询数据源 <a class="header-anchor" href="#车号-交路查询数据源" aria-label="Permalink to &quot;车号 / 交路查询数据源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据源</th><th>描述</th></tr></thead><tbody><tr><td><strong>Rail.re</strong>（默认）</td><td>综合车型信息与交路数据</td></tr><tr><td><strong>RailGo</strong></td><td>综合车型信息与交路数据</td></tr><tr><td><strong>MoeFactory</strong></td><td>全面的车型信息，第三方数据源</td></tr></tbody></table><h3 id="车站查询数据源" tabindex="-1">车站查询数据源 <a class="header-anchor" href="#车站查询数据源" aria-label="Permalink to &quot;车站查询数据源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据源</th><th>描述</th></tr></thead><tbody><tr><td><strong>MoeFactory</strong>（默认）</td><td>提供详细的车站时刻与席别信息</td></tr><tr><td><strong>携程</strong></td><td>备选数据源</td></tr></tbody></table><hr><h2 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><strong>自动检测更新</strong></td><td>应用启动时自动检测新版本，有更新时弹窗提示</td></tr><tr><td><strong>静默更新数据库</strong></td><td>后台自动下载最新的站名、列车型号等本地数据文件</td></tr></tbody></table><hr><h2 id="数据镜像源" tabindex="-1">数据镜像源 <a class="header-anchor" href="#数据镜像源" aria-label="Permalink to &quot;数据镜像源&quot;">​</a></h2><p>由于某些地区访问 GitHub 可能较慢，EmuTrain 提供三个镜像源选项：</p><table tabindex="0"><thead><tr><th>镜像源</th><th>地址</th></tr></thead><tbody><tr><td><strong>Mirror</strong>（默认）</td><td><code>https://gh-proxy.com/...</code> GitHub 加速镜像</td></tr><tr><td><strong>Gitee</strong></td><td><code>https://raw.giteeusercontent.com/CrYinLang/EmuTrain/...</code></td></tr><tr><td><strong>GitHub</strong></td><td><code>https://raw.githubusercontent.com/CrYinLang/EmuTrain/...</code></td></tr></tbody></table><blockquote><p>切换镜像源后，下次拉取数据时生效。<br> 建议国内用户优先使用 <strong>Mirror</strong> 或 <strong>Gitee</strong>。</p></blockquote><hr><h2 id="应用信息" tabindex="-1">应用信息 <a class="header-anchor" href="#应用信息" aria-label="Permalink to &quot;应用信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>版本号</strong></td><td>点击可手动检查是否有新版本</td></tr><tr><td><strong>开发者</strong></td><td>点击跳转至 GitHub / 抖音主页</td></tr><tr><td><strong>QQ 群</strong></td><td>点击进入用户交流群</td></tr></tbody></table>',32)])])}const u=r(o,[["render",n]]);export{c as __pageData,u as default};
